from typing import Dict, Optional

def buscar_precio(catalogo: Dict[str, float], nombre: str) -> Optional[float]:
    """Devuelve el precio o None si el producto no está en el catálogo."""
    return catalogo.get(nombre)

catalogo = {"teclado": 120.0, "mouse": 45.5}

for producto in ["teclado", "monitor"]:
    precio = buscar_precio(catalogo, producto)
    if precio is None:
        print(f"{producto}: sin precio")
    else:
        print(f"{producto}: {precio:.2f}")

