from dataclasses import dataclass, field
from typing import Dict, Iterable, List

@dataclass(frozen=True)
class Venta:
    producto: str
    sede: str
    unidades: int
    precio: float

    @property
    def importe(self) -> float:
        return round(self.unidades * self.precio, 2)

@dataclass
class Resumen:
    por_sede: Dict[str, float] = field(default_factory=dict)

    def agregar(self, venta: Venta) -> None:
        previo = self.por_sede.get(venta.sede, 0.0)
        self.por_sede[venta.sede] = round(previo + venta.importe, 2)

def cargar(filas: Iterable[Dict[str, str]]) -> List[Venta]:
    """Convierte texto del CSV en objetos validados."""
    return [
        Venta(fila["producto"], fila["sede"], int(fila["unidades"]), float(fila["precio"]))
        for fila in filas
    ]

def resumir(ventas: Iterable[Venta]) -> Resumen:
    resumen = Resumen()
    for venta in ventas:
        resumen.agregar(venta)
    return resumen

filas = [
    {"producto": "teclado", "sede": "Lima", "unidades": "3", "precio": "120.0"},
    {"producto": "monitor", "sede": "Lima", "unidades": "1", "precio": "900.0"},
    {"producto": "mouse", "sede": "Arequipa", "unidades": "5", "precio": "45.5"},
]

