from dataclasses import dataclass, replace

@dataclass(frozen=True)
class Producto:
    nombre: str
    precio: float
    stock: int = 0

    def __post_init__(self) -> None:
        if self.precio < 0:
            raise ValueError(f"precio inválido: {self.precio}")
        if self.stock < 0:
            raise ValueError(f"stock inválido: {self.stock}")

    @property
    def disponible(self) -> bool:
        return self.stock > 0

    def con_stock(self, n: int) -> "Producto":
        return replace(self, stock=n)

teclado = Producto("teclado", 120.0, 3)
print(teclado, teclado.disponible)
print(teclado.con_stock(0).disponible)

try:
    Producto("monitor", -1.0, 2)
except ValueError as error:
    print("ValueError:", error)

from dataclasses import dataclass, field
from typing import List, Optional

def promedio(notas: List[float]) -> float:
    if not notas:
        return 0.0
    return round(sum(notas) / len(notas), 2)

@dataclass
class Estudiante:
    nombre: str
    notas: List[float] = field(default_factory=list)

    @property
    def promedio(self) -> float:
        return promedio(self.notas)

def mejor(estudiantes: List[Estudiante]) -> Optional[str]:
    if not estudiantes:
        return None
    return max(estudiantes, key=lambda e: e.promedio).nombre

clase = [
    Estudiante("Ana", [18.0, 16.5, 19.0]),
    Estudiante("Luis", [12.0, 14.0, 13.5]),
]
print(promedio([]))
print(clase[0].promedio)
print(mejor(clase))
print(mejor([]))

